<script setup lang="ts">
import {ref,onMounted,watch} from 'vue';import {useRoute} from 'vue-router';import {post,safeOfficialUrl} from '../api/client';import {indicator,time} from '../presentation/zh';
type Row=Record<string,any>;const props=defineProps<{token:string}>();const route=useRoute();const series=ref(''),evidence=ref(String(route.query.evidence||'')),catalog=ref<Row[]>([]),observations=ref<Row[]>([]),history=ref<Row[]>([]),selected=ref<Row>(),error=ref(''),busy=ref(false),reproduction=ref<Row>(),templates=ref<Row>();
async function loadSeries(){if(!series.value)return;const d=await post<Row>('/macro-changes/detail',props.token,{series:series.value,page:0});observations.value=d.observations||[];if(!observations.value.some(r=>r.evidence_id===evidence.value))evidence.value=observations.value.find(r=>r.metadata)?.evidence_id||'';}
async function selectSnapshot(row:Row){selected.value=row;reproduction.value=undefined;series.value=row.report.series_id;await loadSeries();const proof=row.report.inputs.observations[0];if(!observations.value.some(o=>o.evidence_id===proof.evidence_id))observations.value.unshift(proof);evidence.value=proof.evidence_id;}
async function loadHistory(){history.value=await post<Row[]>('/transmission/query',props.token,{page:0});}
async function analyze(){busy.value=true;error.value='';reproduction.value=undefined;try{selected.value=await post<Row>('/transmission/analyze',props.token,{evidenceId:evidence.value,asOf:new Date().toISOString()});await loadHistory();}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function reproduce(){if(!selected.value)return;try{reproduction.value=await post<Row>('/transmission/reproduce',props.token,{id:selected.value.id});}catch(e){error.value=(e as Error).message}}
async function init(){busy.value=true;error.value='';try{[catalog.value,templates.value]=await Promise.all([post<Row[]>('/macro-changes/catalog',props.token,{page:0}),post<Row>('/transmission/catalog',props.token)]);if(route.query.event){const input=await post<Row>('/transmission/input',props.token,{eventId:route.query.event});series.value=input.series_id;evidence.value=input.evidence_id;}else series.value=String(route.query.series||catalog.value[0]?.id||'');await loadSeries();await loadHistory();if(route.query.snapshot){const saved=(await post<Row[]>('/transmission/query',props.token,{id:route.query.snapshot,page:0}))[0];if(saved)await selectSnapshot(saved);}}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(init);watch(()=>route.fullPath,init);
</script>
<template><section class="panel transmission"><h2>全球金融事件影响传导研究</h2><p>官方事实与数学计算、经济机制、研究假设、市场实际验证分别展示。机制适用不等于经济影响已经发生。</p><p v-if="error" role="alert">{{error}}</p><p v-if="busy" role="status">正在核验真实观测与研究证据…</p><div class="filters"><label>真实宏观指标<select v-model="series" @change="selected=undefined;loadSeries()"><option v-for="s in catalog" :key="s.id" :value="s.id">{{indicator(s.id)}} · {{s.id}}</option></select></label><label>研究当前观测<select v-model="evidence"><option v-for="o in observations" :key="o.evidence_id" :value="o.evidence_id">{{o.observation_date}} · {{o.original_value}} · {{o.verification_status}}</option></select></label><button :disabled="busy||!evidence" @click="analyze">生成证据约束研究快照</button></div><p>前值从同序列截止范围内的前一期真实观测取得；缺失期、未核验字段或口径不一致时阻止研究，不跳过坏输入。</p><details><summary>机制知识库与适用前提</summary><p>{{templates?.status}} · {{templates?.version}}</p><article v-for="t in templates?.templates" :key="t.id"><h3>{{t.name}}</h3><p>适用前提：{{t.conditions.join('；')}}</p><p>所需证据：{{t.evidence.join('；')}}</p><p>反面条件：{{t.contradictions.join('；')}}</p></article></details><template v-if="selected"><h3>{{selected.report.title}}</h3><p>研究创建 {{time(selected.created_at)}} · 证据截止 {{time(selected.as_of)}} · {{selected.report.generated_by}}</p><p>{{selected.report.source_boundary}}</p><h3>已确认事实与可复算计算</h3><p>{{selected.report.fact_status}} · {{selected.report.direction}}</p><p>当前值 {{selected.report.calculation.current_value}} · 前值 {{selected.report.calculation.previous_value}} · 绝对变化 {{selected.report.calculation.delta}} {{selected.report.calculation.delta_unit}} · 相对变化 {{selected.report.calculation.relative_pct??'不适用'}}{{selected.report.calculation.relative_pct!=null?'%':''}} · 基点 {{selected.report.calculation.basis_points??'不适用'}}</p><p>{{selected.report.calculation.formula}} · {{selected.report.calculation.rule_version}}</p><article v-for="o in selected.report.inputs.observations" :key="o.evidence_id"><p>{{o.observation_date}} · 原始值 {{o.original_value}} · {{o.metadata.UNIT}} / {{o.metadata.CURRENCY_DENOM||'无币种分母'}} · {{o.verification_status}}</p><p>官方发布 {{time(o.source_published_at,'官方发布时间未知')}} · 采集 {{time(o.collected_at)}} · 本地版本 {{o.local_version_id}}</p><code>证据 {{o.evidence_id}} · SHA-256 {{o.raw_content_hash}}</code><a v-if="safeOfficialUrl(o.source_url)" :href="o.source_url" target="_blank" rel="noopener noreferrer">查看原始官方证据</a></article><h3>条件性传导路径与研究假设</h3><article class="hypothesis" v-for="m in selected.report.mechanisms" :key="m.mechanism_id"><h4>{{m.mechanism_name_zh}}</h4><p>真实变量 → 可复算变化 → {{m.mechanism_name_zh}} → 产业适用性待核验 → 企业敞口证据不足 → 市场反应尚未验证</p><p>{{m.status}} · {{m.hypothesis_status}}</p><p>{{m.matched_basis}}</p><p>{{m.hypothesis}}</p><p>已有条件：{{m.known_conditions.join('；')}}</p><p>待核验条件：{{m.unknown_conditions.join('；')}}</p><p>反面解释与可能失效条件：{{m.contradiction_conditions.join('；')}}</p><p>{{m.counter_evidence_status}}</p><p>机制版本 {{m.mechanism_version}} · {{m.review_status}}</p><details><summary>反向溯源节点</summary><p v-for="n in selected.report.paths.find((p:Row)=>p.id===m.mechanism_id)?.nodes" :key="n.id">{{n.id}} · {{n.status}} · 父节点 {{n.parent||'原始事实证据'}} · {{n.evidence_ids?.join('、')||n.calculation_id||''}}</p></details></article><h3>企业关系与经营敞口</h3><p>{{selected.report.exposure_status}}</p><p>{{selected.report.industry_status}}</p><p>法人登记、会计并表、证券发行、行业归属与客户供应、区域收入、外币收入、外币成本、融资敞口分别核验。GLEIF并表不能证明供应链或外币敞口。</p><p v-if="!selected.report.verified_relations.length">暂无本研究适用的已核实实体关系</p><article v-for="r in selected.report.verified_relations" :key="r.id"><p>{{r.explanation}} · 原始类型 {{r.type}} · 证据 {{r.evidence_id}}</p></article><h3>市场实际验证</h3><p>{{selected.report.market_status}}</p><p>没有合法时点一致的行情或其他市场观测，不生成证券清单、涨跌幅或企业利润影响。</p><h3>持续验证条件</h3><p v-for="c in selected.report.monitor_conditions" :key="c">{{c}}</p><h3>来源与版本审计</h3><code>研究快照 {{selected.id}} · {{selected.report.research_version}} · 输入哈希 {{selected.input_hash}}</code><button @click="reproduce">复算冻结研究快照</button><p v-if="reproduction">{{reproduction.reproduced?'冻结输入、计算和机制复核通过':'复核未通过'}}</p><a :href="'#/research?event='+selected.report.event_id">返回S64原始事件</a> · <a :href="'#/macro?series='+selected.report.series_id">返回S65宏观观测</a></template><h3>研究历史版本</h3><p v-if="!history.length">尚无当前身份保存的传导研究快照</p><button v-for="r in history" :key="r.id" @click="selectSnapshot(r)">{{r.report.title}} · {{time(r.created_at)}}</button></section></template>
<style scoped>.transmission{min-width:0;font-size:14px}.filters{display:flex;gap:12px;flex-wrap:wrap}.filters label{display:flex;flex-direction:column;gap:6px;max-width:100%}select{max-width:100%;width:420px}article{border-bottom:1px solid #35445b;padding:16px 0}.hypothesis{border-left:3px solid #d3af55;padding-left:14px}p,code{overflow-wrap:anywhere}code,a{display:block;margin:8px 0}h3{margin-top:24px}button{margin:6px 8px 6px 0}</style>
